pub fn get_icon(name: &str) -> Option<&'static str> {
    match name {
        "message-square" => Some(ICON_MESSAGE_SQUARE),
        "bar-chart" => Some(ICON_BAR_CHART),
        "link" => Some(ICON_LINK),
        "radio" => Some(ICON_RADIO),
        "file-text" => Some(ICON_FILE_TEXT),
        "zap" => Some(ICON_ZAP),
        "monitor" => Some(ICON_MONITOR),
        "settings" => Some(ICON_SETTINGS),
        "bug" => Some(ICON_BUG),
        "scroll-text" => Some(ICON_SCROLL_TEXT),
        "folder" => Some(ICON_FOLDER),
        "menu" => Some(ICON_MENU),
        "x" => Some(ICON_X),
        "check" => Some(ICON_CHECK),
        "arrow-down" => Some(ICON_ARROW_DOWN),
        "copy" => Some(ICON_COPY),
        "search" => Some(ICON_SEARCH),
        "brain" => Some(ICON_BRAIN),
        "book" => Some(ICON_BOOK),
        "loader" => Some(ICON_LOADER),
        "wrench" => Some(ICON_WRENCH),
        "file-code" => Some(ICON_FILE_CODE),
        "edit" => Some(ICON_EDIT),
        "pen-line" => Some(ICON_PEN_LINE),
        "paperclip" => Some(ICON_PAPERCLIP),
        "globe" => Some(ICON_GLOBE),
        "image" => Some(ICON_IMAGE),
        "smartphone" => Some(ICON_SMARTPHONE),
        "plug" => Some(ICON_PLUG),
        "circle" => Some(ICON_CIRCLE),
        "puzzle" => Some(ICON_PUZZLE),
        "users" => Some(ICON_USERS),
        "database" => Some(ICON_DATABASE),
        "clock" => Some(ICON_CLOCK),
        "play" => Some(ICON_PLAY),
        "square" => Some(ICON_SQUARE),
        "trash" => Some(ICON_TRASH),
        "plus" => Some(ICON_PLUS),
        "minus" => Some(ICON_MINUS),
        "chevron-down" => Some(ICON_CHEVRON_DOWN),
        "chevron-right" => Some(ICON_CHEVRON_RIGHT),
        "external-link" => Some(ICON_EXTERNAL_LINK),
        "refresh-cw" => Some(ICON_REFRESH_CW),
        "alert-circle" => Some(ICON_ALERT_CIRCLE),
        "info" => Some(ICON_INFO),
        "logout" => Some(ICON_LOGOUT),
        "discord" => Some(ICON_DISCORD),
        "telegram" => Some(ICON_TELEGRAM),
        "whatsapp" => Some(ICON_WHATSAPP),
        "slack" => Some(ICON_SLACK),
        "github" => Some(ICON_GITHUB),
        "signal" => Some(ICON_SIGNAL),
        "matrix" => Some(ICON_MATRIX),
        "mattermost" => Some(ICON_MATTERMOST),
        "google-chat" => Some(ICON_GOOGLE_CHAT),
        "line" => Some(ICON_LINE),
        "feishu" => Some(ICON_FEISHU),
        "irc" => Some(ICON_IRC),
        "msteams" => Some(ICON_MSTEAMS),
        "home" => Some(ICON_HOME),
        "save" => Some(ICON_SAVE),
        _ => None,
    }
}

pub fn get_icon_or_fallback(name: &str) -> &'static str {
    get_icon(name).unwrap_or(ICON_CIRCLE)
}

pub fn get_platform_icon(platform: &str) -> &'static str {
    let platform_lower = platform.to_lowercase();
    match platform_lower.as_str() {
        "discord" => ICON_DISCORD,
        "telegram" => ICON_TELEGRAM,
        "whatsapp" => ICON_WHATSAPP,
        "slack" => ICON_SLACK,
        "signal" => ICON_SIGNAL,
        "matrix" => ICON_MATRIX,
        "mattermost" => ICON_MATTERMOST,
        "googlechat" | "google-chat" | "google_chat" => ICON_GOOGLE_CHAT,
        "line" => ICON_LINE,
        "feishu" | "lark" => ICON_FEISHU,
        "irc" => ICON_IRC,
        "msteams" | "teams" => ICON_MSTEAMS,
        "github" => ICON_GITHUB,
        _ => ICON_GLOBE,
    }
}
